\label{thm:rough} 
Let $f\colon M^n\to \overline{M}^{n+1}$, $n\geq 3$, be a {\rm(}smooth{\rm)} isometric immersion of a space of constant sectional curvature $M^n = M^n(\kappa)$ in a product $\overline{M}^{n+1}=\overline{M}^{k}(\kappa_1)\times \overline{M}^{n-k+1}(\kappa_2)$ of two space forms.
\begin{enumerate}[label={\rm{(\roman*)}}]
\item\label{it:rough1} If $\kappa_1 \kappa_2 \ne 0$, then $\kappa = \frac{\kappa_1\kappa_2}{\kappa_1+\kappa_2}$ and one of the following holds:
 \begin{enumerate}[label={\rm{(\roman{enumi}.\alph*)}}]
\item\label{it:rough2} Either  $\kappa_1\kappa_2<0$, with $\kappa_1+\kappa_2<0$, or $\kappa_1,\kappa_2<0$, and $f(M^n)$ is an open subset of the intersection of the embedded $\overline{M}^{n+1} \subset \mathbb{R}^{n+3, \sigma}$, $\sigma\in\{1,2\}$, with a degenerate hyperplane;
\item\label{it:rough3} $n=3$, $k = 2$, and $f(M^3)$ is obtained from a hypersurface with constant sectional curvature $\varepsilon/2$ in the product $\overline{M}^2(\varepsilon) \times \overline{M}^2(\varepsilon), \varepsilon = \pm 1$, {\rm(}such hypersurfaces are classified in \cites{LVWY,LVWYhyp}{\rm)} by an affine rescaling procedure.\vspace{.5ex}
\end{enumerate}
\item\label{it:rough4} If one of the factors is flat, then $f$ is as given in \cite[Theorems~7.1 and 7.2]{MaT} for $k=1$ and  {\cite[Theorems~11 and 12]{CT}} for $k\ge2$.
\end{enumerate}

\label{thm: flatHrough} 
If $f\colon M^n\to \mathbb{R}^k\times \mathbb{H}^{n-k+1}\subset \mathbb{R}^k\times \mathbb{R}^{n-k+2, 1}=\mathbb{R}^{n+2, 1}$, $1\leq k\leq n-3$,  
is a flat hypersurface, then $f(M^n)$ is an open subset of the intersection of $\mathbb{R}^k\times \mathbb{H}^{n-k+1}$ with an affine hyperplane of $\mathbb{R}^{n+2, 1}$ orthogonal to a light-like vector in $\mathbb{R}^{n+2, 1}$.

\label{lem:grad}
    If a hypersurface $f\colon M^{n}\to \overline{M}^{k}(\kappa_1)\times \overline{M}^{n-k+1}(\kappa_2)$ satisfies $S\mathcal{R} = \mathcal{R} S$, then $\zeta$ is {\rm(}locally{\rm)} a gradient vector field.
\begin{proof}
    It suffices to show that the one-form $\zeta^\flat =\<\zeta,\cdot\>$ is closed. Since $S\mathcal{R} = \mathcal{R} S$, the endomorphism $A:=(tI-\mathcal{R})S$ is symmetric. Then, using~\eqref{derS2}, a direct computation yields
    $d\zeta^\flat (X,Y) = \<AX,Y\> - \<AY,X\> = 0$ for all $X,Y\in\Gamma(TM^n)$. Thus, $d\zeta^\flat = 0$.
\end{proof}

\label{lem:flatbi}
    Let $\omega: V^n \times V^n \to U^{p,q}$, $\dim U<\dim V$, be a flat symmetric bilinear form. Suppose that one of the following holds{\rm:}
    \begin{enumerate}[label={\rm{(\alph*)}}, ref=\alph*]
        \item\label{it:pode} $q=0${\rm;} 
        \item\label{it:symim} $q=1$ and $\mathcal{I}(\omega) = U^{p,1}$.
    \end{enumerate}
Then $\dim \mathcal{N}(\omega) \ge \dim V - \dim U$.

\label{ex:3.6} Let  $\gamma_1\colon I_1\subset \mathbb{R}\to \overline{M}^{2}(\kappa_1)$ and $\gamma_2\colon I_2\subset \mathbb{R}\to \overline{M}^{2}(\kappa_2)$, where $I_1$ and $I_2$ are open intervals and $\kappa_1\kappa_2>0$,  be smooth unit-speed curves with curvatures $\lambda_1$ and $\lambda_2$, respectively, let $N_1$ and $N_2$ be unit normal vector fields along $\gamma_1$ and $\gamma_2$, respectively, and let $\theta\in \mathbb{R}$.  Define $f\colon \mathbb{R}\times I_1\times I_2\to \overline{M}^2(\kappa_1)\times\overline{M}^{2}(\kappa_2)$  by 
 \begin{equation}\label{param}
f(s, u_1, u_2)=(f_1(s, u_1), f_2(s, u_2)),
\end{equation}
where
 \begin{equation}\label{f1}
 f_1(s, u_1)=C_{\varepsilon}(s \cos \theta  / R_1) \gamma_1(u_1) + R_1 S_{\varepsilon}(s\cos \theta  / R_1)N_1(u_1)
\end{equation}
and
 \begin{equation}\label{f2}
f_2(s, u_2)=C_{\varepsilon}( s\sin \theta / R_2) \gamma_2(u_2) + R_2 S_{\varepsilon}(s\sin \theta  / R_2)N_2(u_2).
\end{equation}
Here $\varepsilon=\kappa_1/|\kappa_1|=\kappa_2/|\kappa_2|$, $\kappa_i=\varepsilon/R_i^2$, and $C_\varepsilon$ and $S_\varepsilon$ are as in \eqref{cs}. 
Restricted to the open subset of its regular points, the map $f$ defines a hypersurface having the coordinate vector fields as principal directions, with $0$ as one of its principal curvatures, the $s$-coordinate curves being its associated  curvature lines, and two nonzero principal curvatures
\begin{equation}\label{eq:pc}
\frac{- \sin\theta }{R_1}\frac{\varepsilon S_\varepsilon(s \cos \theta/R_1)+\lambda_1 R_1 C_\varepsilon(s \cos\theta/R_1)}{C_\varepsilon(s \cos\theta/R_1)-\lambda_1 R_1  S_\varepsilon(s \cos\theta/R_1)}, \,\, \frac{\cos \theta}{R_2}\frac{\varepsilon S_\varepsilon(s \sin \theta/R_2)+\lambda_2 R_2 C_\varepsilon(s \sin\theta/R_2)}{C_\varepsilon(s \sin\theta/R_2)-\lambda_2 R_2  S_\varepsilon(s \sin \theta/R_2)}.
\end{equation}
The coordinate vector fields are also principal directions of the tensor $\mathcal{R}$ defined in \eqref{R}, with eigenvalues
$0, 1$ and $\sin^2 \theta$, the latter corresponding to the coordinate vector field $\partial/\partial s$. In particular, 
the tensors $S$ and $\mathcal{R}$ satisfy $S\mathcal{R}=\mathcal{R} S$.
Taking $\theta=\arcsin{\left(\frac{\kappa_1}{\kappa_1+\kappa_2}\right)^{1/2}}$, the eigenfunction of $\mathcal{R}$ taking values in $(0,1)$ has the constant value $r=\sin^2\theta=\frac{\kappa_1}{\kappa_1+\kappa_2}$, hence
 the product angle function has the constant value $C=2r-1=\frac{\kappa_1-\kappa_2}{\kappa_1+\kappa_2}$.
 Moreover, choosing the curves $\gamma_1$ and $\gamma_2$ to have constant curvatures $\lambda_1$ and $\lambda_2$, respectively,  with $\lambda_1\lambda_2=(\kappa_1\kappa_2)^{1/2}$,
one can check using Gauss equations that $f$ has constant sectional curvature  $\kappa = \frac{\kappa_1\kappa_2}{\kappa_1+\kappa_2}$.

\label{mainthmb}  
Let $f\colon M^n\to \overline{M}^{n+1}$, $n\geq 3$, be a {\rm(}smooth{\rm)} isometric immersion of a space of constant sectional curvature $M^n = M^n(\kappa)$ in a product $\overline{M}^{n+1}=\overline{M}^{k}(\kappa_1)\times \overline{M}^{n-k+1}(\kappa_2)$ of two space forms.

\begin{enumerate}[label={\rm{(\roman*)}}]
\item\label{it:thm11} If $\overline{M}^{n+1}=\mathbb{R}\times \overline{M}^{n}(\kappa_2)$, $\kappa_2\neq 0$, then $f$ is as in \cite[Theorems~7.1 and 7.2]{MaT}{\rm;}
\item\label{it:thm12} If $\overline{M}^{n+1}=\mathbb{R}^k\times \overline{M}^{n-k+1}(\kappa_2)$, $2\leq k\leq n-1$, $\kappa_2\neq 0$,  then $f$ is as in  {\cite[Theorems~11 and 12]{CT}}{\rm;}
 \item If $\kappa_1\kappa_2\neq 0$, then $\kappa = \frac{\kappa_1\kappa_2}{\kappa_1+\kappa_2}$ and one of the following holds{\rm:}
        \begin{enumerate}[label={\rm{(\roman{enumi}.\alph*)}}]
            \item\label{it:thm13} Either  $\kappa_1\kappa_2<0$, with $\kappa_1+\kappa_2<0$, or $\kappa_1,\kappa_2<0$, and there exists an open subset $\mathcal{U}\subset \overline{M}^n(\kappa)$ and an isometry $\phi\colon \mathcal{U}\to M^n$ such that $f\circ \phi$ is the restriction to $\mathcal{U}$ of an isometric embedding of $\overline{M}^{n}(\kappa)$ into $ \overline{M}^{n+1} \subset \overline{M}^{n+2,1}(\kappa)$ as in Examples~\ref{ex:int1} or \ref{ex:int2}, respectively{\rm;}
            \item\label{it:thm14} $n=3$, $k=2$,   $\kappa_1\kappa_2>0$, and  $f$ is constructed,  by means of the rescailing procedure in Proposition \ref{prop:scale}, from the examples in  \cites{LVWY,LVWYhyp} with  $\operatorname{rk} S=2$ for the case $\kappa_1=\kappa_2=\pm1$.
        \end{enumerate}
\end{enumerate}
